import React, { useState, useEffect } from 'react';

const MODE_COLORS = {
  work: '#2196F3',    // Blue
  leisure: '#FFCA28', // Yellow/Amber
  break: '#00BCD4',   // Cyan
  inactive: '#9E9E9E' // Gray
};

const processIntervals = (rawData) => {
  const intervals = [];
  let currentMode = null;
  let startTime = null;
  let lastTimestamp = null;
  const INACTIVE_THRESHOLD = 30 * 60 * 1000; // 30 minutes in milliseconds

  // Variables for tracking consecutive zeros
  let zeroCount = 0;
  let zeroStartTime = null;

  // Get day start (midnight)
  const firstTimestamp = new Date(rawData[0].timestamp);
  const dayStart = new Date(firstTimestamp.getFullYear(), firstTimestamp.getMonth(), firstTimestamp.getDate());

  // Find first activity
  let firstActivity = null;
  let firstActivityMode = null;
  for (const row of rawData) {
    if (row.elapsed_time === 0) {
      firstActivity = new Date(row.timestamp);
      if (row.active === 0) firstActivityMode = 'break';
      else if (row.active === 1) firstActivityMode = 'work';
      else if (row.active === 2) firstActivityMode = 'leisure';
      break;
    }
  }

  // Add inactive period before first activity
  if (firstActivity && firstActivity > dayStart) {
    intervals.push({
      start: dayStart,
      end: firstActivity,
      mode: 'inactive'
    });
  }

  // Process all intervals
  for (const row of rawData) {
    const timestamp = new Date(row.timestamp);
    const active = row.active;

    // Check for gaps (program shutdown periods)
    if (lastTimestamp) {
      const timeGap = timestamp - lastTimestamp;
      if (timeGap > INACTIVE_THRESHOLD) {
        intervals.push({
          start: lastTimestamp,
          end: timestamp,
          mode: 'inactive'
        });
        currentMode = null;
      }
    }

    // Track consecutive zeros
    if (active === 0) {
      if (zeroCount === 0) {
        zeroStartTime = timestamp;
      }
      zeroCount++;
    } else {
      if (zeroCount >= 5 && zeroStartTime) {
        intervals.push({
          start: zeroStartTime,
          end: timestamp,
          mode: 'break'
        });
        currentMode = null;
      }
      zeroCount = 0;
      zeroStartTime = null;
    }

    // Determine mode
    let mode;
    if (active === 1) mode = 'work';
    else if (active === 2) mode = 'leisure';
    else if (active === 0) {
      mode = zeroCount >= 5 ? 'break' : 'break';
    } else mode = 'inactive';

    // Create or update interval
    if (currentMode === null) {
      startTime = timestamp;
      currentMode = mode;
    } else if (mode !== currentMode) {
      intervals.push({
        start: startTime,
        end: timestamp,
        mode: currentMode
      });
      startTime = timestamp;
      currentMode = mode;
    }

    lastTimestamp = timestamp;
  }

  // Add final interval if needed
  if (startTime && currentMode) {
    intervals.push({
      start: startTime,
      end: lastTimestamp,
      mode: currentMode
    });
  }

  return intervals;
};

const formatHour = (hour) => {
  return hour.toString().padStart(2, '0');
};

const ActivityTimeline = ({ data }) => {
  const [intervals, setIntervals] = useState([]);

  useEffect(() => {
    if (data) {
      const processedIntervals = processIntervals(data);
      setIntervals(processedIntervals);
    }
  }, [data]);

  // Create hour labels
  const hourLabels = [];
  for (let h = 0; h <= 24; h += 4) {
    hourLabels.push(h);
  }

  return (
    <div className="w-full h-16 py-2">
      <div className="relative w-full h-8 bg-gray-800 rounded">
        {intervals.map((interval, index) => {
          const startHour = interval.start.getHours() + interval.start.getMinutes() / 60;
          const endHour = interval.end.getHours() + interval.end.getMinutes() / 60;

          return (
            <div
              key={index}
              className="absolute h-full"
              style={{
                left: `${(startHour / 24) * 100}%`,
                width: `${((endHour - startHour) / 24) * 100}%`,
                backgroundColor: MODE_COLORS[interval.mode]
              }}
              title={`${interval.start.toLocaleTimeString()} - ${interval.end.toLocaleTimeString()} (${interval.mode})`}
            />
          );
        })}
      </div>
      <div className="relative w-full h-6 mt-1">
        {hourLabels.map((hour) => (
          <div 
            key={hour} 
            className="absolute text-xs text-gray-400"
            style={{ left: `${(hour / 24) * 100}%`, transform: 'translateX(-50%)' }}
          >
            {formatHour(hour)}
          </div>
        ))}
      </div>
    </div>
  );
};

export default ActivityTimeline;
